import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_kd1_forward(torch::Tensor x,
                                  torch::Tensor weight,
                                  c10::optional<torch::Tensor> bias,
                                  int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define MAX_D 32

__global__ void conv3d_kd1_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ Bias,
    float* __restrict__ Y,
    int N, int Cin, int H, int Win, int Dd,
    int Cout, int KH, int KW,
    int stride, int padding, int dilation,
    int groups,
    int Hout, int Wout, int Dout,
    int Cin_per_group, int Cout_per_group)
{
    const int ow = blockIdx.x * blockDim.x + threadIdx.x;
    const int oh = blockIdx.y * blockDim.y + threadIdx.y;

    const int noc = blockIdx.z;
    const int n   = noc / Cout;
    const int oc  = noc % Cout;

    const int group    = oc / Cout_per_group;
    const int ic_start = group * Cin_per_group;

    // Shared memory for the (small) weight kernel of this output channel.
    extern __shared__ float sW_raw[];
    auto sW = make_tensor(
        make_smem_ptr(sW_raw),
        make_shape(Cin_per_group, KH, KW),
        make_stride(KH * KW, KW, 1)
    );

    // Global weight tensor view (Cout, Cin_per_group, KH, KW)
    auto mW = make_tensor(
        make_gmem_ptr(Wt),
        make_shape(Cout, Cin_per_group, KH, KW),
        make_stride(Cin_per_group * KH * KW, KH * KW, KW, 1)
    );

    const int total_w  = Cin_per_group * KH * KW;
    const int tid       = threadIdx.y * blockDim.x + threadIdx.x;
    const int nThreads   = blockDim.x * blockDim.y;

    for (int idx = tid; idx < total_w; idx += nThreads) {
        int kw_  = idx % KW;
        int tmp  = idx / KW;
        int kh_  = tmp % KH;
        int icl  = tmp / KH;
        sW(icl, kh_, kw_) = mW(oc, icl, kh_, kw_);
    }
    __syncthreads();

    // Global input/output tensors for this batch element n.
    const int64_t sXc = (int64_t)H * Win * Dd;
    const int64_t sXh = (int64_t)Win * Dd;
    const int64_t sXw = (int64_t)Dd;

    auto mX = make_tensor(
        make_gmem_ptr(X + (int64_t)n * Cin * sXc),
        make_shape(Cin, H, Win, Dd),
        make_stride(sXc, sXh, sXw, Int<1>{})
    );

    const int64_t sYc = (int64_t)Hout * Wout * Dout;
    const int64_t sYh = (int64_t)Wout * Dout;
    const int64_t sYw = (int64_t)Dout;

    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * Cout * sYc),
        make_shape(Cout, Hout, Wout, Dout),
        make_stride(sYc, sYh, sYw, Int<1>{})
    );

    if (oh < Hout && ow < Wout) {
        float acc[MAX_D];
        float bval = (Bias != nullptr) ? Bias[oc] : 0.0f;
        #pragma unroll
        for (int od = 0; od < MAX_D; ++od) acc[od] = bval;

        for (int icl = 0; icl < Cin_per_group; ++icl) {
            int ic = ic_start + icl;
            for (int kh = 0; kh < KH; ++kh) {
                int ih = oh * stride - padding + kh * dilation;
                if (ih < 0 || ih >= H) continue;
                for (int kw = 0; kw < KW; ++kw) {
                    int iw = ow * stride - padding + kw * dilation;
                    if (iw < 0 || iw >= Win) continue;

                    float wval = sW(icl, kh, kw);

                    #pragma unroll
                    for (int od = 0; od < Dout; ++od) {
                        int id = od * stride - padding; // kernel depth = 1
                        if (id < 0 || id >= Dd) continue;
                        float xval = mX(ic, ih, iw, id);
                        acc[od] += xval * wval;
                    }
                }
            }
        }

        for (int od = 0; od < Dout; ++od) {
            mY(oc, oh, ow, od) = acc[od];
        }
    }
}

torch::Tensor conv3d_kd1_forward(torch::Tensor x,
                                  torch::Tensor weight,
                                  c10::optional<torch::Tensor> bias,
                                  int stride, int padding, int dilation, int groups) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA if provided");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(x.dim() == 5, "x must be [N, C, H, W, D]");
    TORCH_CHECK(weight.dim() == 5, "weight must be [Cout, Cin/groups, KH, KW, KD]");
    TORCH_CHECK(weight.size(4) == 1, "kernel depth must be 1");

    int64_t N   = x.size(0);
    int64_t Cin = x.size(1);
    int64_t H   = x.size(2);
    int64_t Win = x.size(3);
    int64_t Dd  = x.size(4);

    int64_t Cout          = weight.size(0);
    int64_t Cin_per_group = weight.size(1);
    int64_t KH            = weight.size(2);
    int64_t KW            = weight.size(3);

    TORCH_CHECK(groups > 0, "groups must be > 0");
    TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
    TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");
    TORCH_CHECK(Cin_per_group == Cin / groups, "weight.size(1) mismatch with groups");
    int64_t Cout_per_group = Cout / groups;

    TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
    TORCH_CHECK(padding >= 0, "padding must be >= 0");

    int64_t Hout = (H   + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
    int64_t Wout = (Win + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;
    int64_t Dout = (Dd  + 2 * padding - 1) / stride + 1; // kernel depth = 1

    TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "Invalid output size computed");
    TORCH_CHECK(Dout <= MAX_D, "Output depth exceeds supported maximum (", MAX_D, ")");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (bias.has_value()) {
        b_c = bias.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
        b_ptr = b_c.data_ptr<float>();
    }

    auto y = torch::empty({N, Cout, Hout, Wout, Dout}, x.options());

    dim3 block(16, 16);
    dim3 grid(
        (unsigned)((Wout + block.x - 1) / block.x),
        (unsigned)((Hout + block.y - 1) / block.y),
        (unsigned)(N * Cout)
    );

    size_t smem_bytes = (size_t)Cin_per_group * KH * KW * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv3d_kd1_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)H, (int)Win, (int)Dd,
        (int)Cout, (int)KH, (int)KW,
        (int)stride, (int)padding, (int)dilation,
        (int)groups,
        (int)Hout, (int)Wout, (int)Dout,
        (int)Cin_per_group, (int)Cout_per_group
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv3d_kd1_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_kd1_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_kd1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    3D convolution with an asymmetric input and square kernel, where the
    kernel size along the last spatial ("depth") dimension is fixed to 1.
    Implemented with a single custom CUDA kernel using CuTe tensors/layouts.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        K = self.kernel_size
        Cin_per_group = self.in_channels // self.groups

        # Weight layout matches PyTorch Conv3d: [Cout, Cin/groups, KH, KW, KD] with KD = 1
        self.weight = nn.Parameter(torch.empty(self.out_channels, Cin_per_group, K, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_kd1_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

