    TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
    TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");
    TORCH_CHECK(Cin_per_group == Cin / groups, "weight.size(1) mismatch with groups");
    int64_t Cout_per_group = Cout / groups;

    TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
    TORCH_CHECK(padding >= 0, "padding must be >= 0");

    int64_t Hout = (H   + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
    int64_t Wout = (Win + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;
    int64_t Dout = (Dd  + 2 * padding - 1) / stride + 1; // kernel depth = 1

    TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "Invalid output size computed");
    TORCH_CHECK(Dout <= MAX_D, "Output depth exceeds supported maximum (", MAX_D, ")");

