_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    """Resolve the compiled entry point, raising if the PTX module is invalid."""
    module = _get_module()
    return module.function("conv3d_kd1_kernel")


class ModelNew(nn.Module):
    """
    3D convolution with an asymmetric input and square kernel, where the
    kernel size along the last spatial ("depth") dimension is fixed to 1.
    Implemented with a hand-written NVPTX kernel launched via
    `cutegen.ptx_runtime.PtxModule`.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        K = self.kernel_size
        Cin_per_group = self.in_channels // self.groups

        # Weight layout matches PyTorch Conv3d: [Cout, Cin/groups, KH, KW, KD] with KD = 1
        self.weight = nn.Parameter(torch.empty(self.out_channels, Cin_per_group, K, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be CUDA"
        assert x.dtype == torch.float32, "x must be float32"

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N, Cin, H, Win, Dd = x_c.shape
        Cout, Cin_per_group, KH, KW, KD = w_c.shape
        assert KD == 1, "kernel depth must be 1"

        groups = self.groups
        stride = self.stride
        padding = self.padding
        dilation = self.dilation

        assert Cin % groups == 0 and Cout % groups == 0
        assert Cin_per_group == Cin // groups
        Cout_per_group = Cout // groups

        Hout = (H + 2 * padding - dilation * (KH - 1) - 1) // stride + 1
        Wout = (Win + 2 * padding - dilation * (KW - 1) - 1) // stride + 1
        Dout = (Dd + 2 * padding - 1) // stride + 1  # kernel depth == 1

        assert Hout > 0 and Wout > 0 and Dout > 0, "Invalid output size computed"
        assert Dout <= MAX_D, f"Output depth exceeds supported maximum ({MAX_D})"

        y = torch.empty((N, Cout, Hout, Wout, Dout), device=x.device, dtype=torch.float32)

        if self.bias is not None:
            b_c = self.bias.contiguous()
            bias_ptr = b_c.data_ptr()
        else:
            b_c = None
            bias_ptr = 0

        block_x, block_y = 16, 16
        grid_x = (Wout + block_x - 1) // block_x
        grid_y = (Hout + block_y - 1) // block_y
        grid_z = N * Cout

        stream = torch.cuda.current_stream(x.device).cuda_stream

        module = _get_module()
        kernel = module.function("conv3d_kd1_kernel")

        kernel.launch(
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, 1),
            shared_mem=0,
            stream=stream,
            args=[
                u64(x_c.data_ptr()),
                u64(w_c.data_ptr()),
                u64(bias_ptr),
                u64(y.data_ptr()),
                i32(N), i32(Cin), i32(H), i32(Win), i32(Dd),
                i32(Cout), i32(KH), i32(KW),
                i32(stride), i32(padding), i32(dilation),
                i32(groups),
                i32(Hout), i32(Wout), i32(Dout),
                i32(Cin_per_group), i32(Cout_per_group),
            ],
        )

        return y
